import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  fromTileLocal,
  nativeLevel,
  type Point,
  place,
  TILE_SIZE,
  type Tile,
  toTileLocal,
} from "@stallion/geometry";
import {
  MAX_WIDTH,
  MIN_WIDTH,
  nearestColour,
  nearestSize,
  PALETTE_RGB,
  type PencilSize,
  rgbHex,
  type Stroke,
  type Point as StrokePoint,
  type StrokeStyle,
  styleOf,
  widthOf,
} from "@stallion/schema";
import getStroke, { type StrokeOptions } from "perfect-freehand";

export const PALETTE: readonly string[] = PALETTE_RGB.map(rgbHex);

export const PENCIL_SIZES: readonly PencilSize[] = ["Small", "Medium", "Large"];

export const WIDTH_PRESETS: readonly number[] = [0.5, 1, 2, 40, 60, 96];

export const WIDTH_SLIDER_STEPS = 100;

const WIDTH_SPAN = Math.log(MAX_WIDTH / MIN_WIDTH);

const roundWidth = (width: number): number =>
  width < 4 ? Math.round(width * 2) / 2 : Math.round(width);

export const clampWidth = (width: number): number =>
  Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, roundWidth(width)));

export const sliderToWidth = (step: number): number =>
  clampWidth(MIN_WIDTH * Math.exp((step / WIDTH_SLIDER_STEPS) * WIDTH_SPAN));

export const widthToSlider = (width: number): number =>
  Math.round((Math.log(clampWidth(width) / MIN_WIDTH) / WIDTH_SPAN) * WIDTH_SLIDER_STEPS);

export const MAX_POINTS = 4096;

export const strokeWorldWidth = (width: number, nativeZoom: number): number =>
  width * 2 ** (nativeZoom - 0.5);

const strokeOptions = (size: number, last: boolean): StrokeOptions => ({
  size,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.4,
  simulatePressure: false,
  last,
});

export const HIGHLIGHTER_ALPHA = 0.4;

export const UNIFORM_PRESSURE = 0.5;

export const outlinePath = (
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): Path2D => {
  const outline = getStroke([...points], strokeOptions(size, last));
  const path = new Path2D();
  const [first, ...rest] = outline;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  path.closePath();
  return path;
};

const centrelinePath = (points: readonly StrokePoint[]): Path2D => {
  const path = new Path2D();
  const [first, ...rest] = points;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  if (rest.length === 0) path.lineTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  return path;
};

export type StrokeInk = { style: StrokeStyle; path: Path2D; lineWidth: number };

export const strokeInk = (
  style: StrokeStyle,
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): StrokeInk => {
  if (style === "Dashed") return { style, path: centrelinePath(points), lineWidth: size };
  const pressed =
    style === "Uniform" ? points.map(([x, y]): StrokePoint => [x, y, UNIFORM_PRESSURE]) : points;
  return { style, path: outlinePath(pressed, size, last), lineWidth: size };
};

export const dashPattern = (lineWidth: number): number[] => [lineWidth, lineWidth * 2.5];

export const paintInk = (
  ctx: CanvasRenderingContext2D,
  ink: StrokeInk,
  colour: string,
  alpha = 1,
): void => {
  const highlighter = ink.style === "Highlighter";
  ctx.globalAlpha = highlighter ? alpha * HIGHLIGHTER_ALPHA : alpha;
  if (highlighter) ctx.globalCompositeOperation = "multiply";
  if (ink.style === "Dashed") {
    ctx.strokeStyle = colour;
    ctx.lineWidth = ink.lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.setLineDash(dashPattern(ink.lineWidth));
    ctx.stroke(ink.path);
    ctx.setLineDash([]);
  } else {
    ctx.fillStyle = colour;
    ctx.fill(ink.path);
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
};

const randomHex = (bytes: number): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");

export const newObjectId = (): string =>
  `${Date.now().toString(36).padStart(9, "0")}${randomHex(6)}`;

export type Draft = {
  objectId: string;
  rgb: number;
  width: number;
  style: StrokeStyle;
  nativeZoom: number;
  points: StrokePoint[];
};

export const startDraft = (
  rgb: number,
  width: number,
  style: StrokeStyle,
  zoom: number,
): Draft => ({
  objectId: newObjectId(),
  rgb,
  width,
  style,
  nativeZoom: nativeLevel(zoom),
  points: [],
});

export const continueDraft = (draft: Draft): Draft => {
  const last = draft.points.at(-1);
  return { ...draft, objectId: newObjectId(), points: last ? [last] : [] };
};

const draftBounds = (draft: Draft): BBox => {
  const margin = strokeWorldWidth(draft.width, draft.nativeZoom);
  const xs = draft.points.map((p) => p[0]);
  const ys = draft.points.map((p) => p[1]);
  return {
    minX: Math.min(...xs) - margin,
    minY: Math.min(...ys) - margin,
    maxX: Math.max(...xs) + margin,
    maxY: Math.max(...ys) + margin,
  };
};

export const finishDraft = (draft: Draft): StoredObject | undefined => {
  if (draft.points.length === 0) return undefined;
  const bbox = draftBounds(draft);
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const stroke: Stroke = {
    type: "Stroke",
    objectId: draft.objectId,
    nativeZoom: draft.nativeZoom,
    bbox,
    colour: nearestColour(draft.rgb),
    rgb: draft.rgb,
    size: nearestSize(draft.width),
    width: draft.width,
    style: draft.style,
    points: draft.points.map(([x, y, pressure]) => {
      const local = toTileLocal(tile, { x, y });
      return [local.x, local.y, pressure];
    }),
  };
  return { tile, object: stroke };
};

export type StrokeFrame = { origin: Point; scale: number; points: StrokePoint[] };

// Path2D keeps float32, so points live relative to the stroke bbox, never the tile.
export const strokeFrame = (tile: Tile, stroke: Stroke): StrokeFrame => {
  const { bbox } = stroke;
  const origin = { x: bbox.minX, y: bbox.minY };
  const extent = Math.max(
    bbox.maxX - bbox.minX,
    bbox.maxY - bbox.minY,
    strokeWorldWidth(widthOf(stroke), stroke.nativeZoom),
  );
  const scale = extent / TILE_SIZE;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    return [(world.x - origin.x) / scale, (world.y - origin.y) / scale, pressure];
  });
  return { origin, scale, points };
};

export const strokeFrameInk = (stroke: Stroke, frame: StrokeFrame): StrokeInk =>
  strokeInk(
    styleOf(stroke),
    frame.points,
    strokeWorldWidth(widthOf(stroke), stroke.nativeZoom) / frame.scale,
    true,
  );

export const draftScreenInk = (
  draft: Pick<Draft, "width" | "style" | "nativeZoom" | "points">,
  toScreen: (world: Point) => Point,
  zoom: number,
): StrokeInk =>
  strokeInk(
    draft.style,
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.width, draft.nativeZoom) * zoom,
    false,
  );

export const translateStroke = (
  tile: Tile,
  stroke: Stroke,
  dx: number,
  dy: number,
): StoredObject | undefined => {
  const bbox = {
    minX: stroke.bbox.minX + dx,
    minY: stroke.bbox.minY + dy,
    maxX: stroke.bbox.maxX + dx,
    maxY: stroke.bbox.maxY + dy,
  };
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    const local = toTileLocal(placed.tile, { x: world.x + dx, y: world.y + dy });
    return [local.x, local.y, pressure];
  });
  return { tile: placed.tile, object: { ...stroke, bbox, points } };
};
import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  fromTileLocal,
  nativeLevel,
  type Point,
  place,
  type Tile,
  toTileLocal,
} from "@stallion/geometry";
import {
  FILLABLE,
  nearestColour,
  nearestSize,
  type Shape,
  type ShapeFill,
  type ShapeKind,
  type StrokeStyle,
  styleOf,
  widthOf,
} from "@stallion/schema";
import { dashPattern, HIGHLIGHTER_ALPHA, newObjectId, strokeWorldWidth } from "./stroke";

export const TINT_ALPHA = 0.2;

export const MIN_SHAPE_PX = 2;

const ARROW_HEAD_SPREAD = 0.5;

export const arrowHeadPx = (width: number): number => width * 3 + 8;

export type ShapeLook = {
  kind: ShapeKind;
  fill: ShapeFill;
  style: StrokeStyle;
  width: number;
  nativeZoom: number;
};

export type ShapeDraft = ShapeLook & { objectId: string; rgb: number; start: Point; end: Point };

export type ShapeInk = {
  kind: ShapeKind;
  filled: boolean;
  style: StrokeStyle;
  start: Point;
  end: Point;
  lineWidth: number;
  head: number;
};

export const shapeLook = (shape: Shape): ShapeLook => ({
  kind: shape.kind,
  fill: shape.fill,
  style: styleOf(shape),
  width: widthOf(shape),
  nativeZoom: shape.nativeZoom,
});

export const shapeWorldPoints = (tile: Tile, shape: Shape): { start: Point; end: Point } => ({
  start: fromTileLocal(tile, { x: shape.start[0], y: shape.start[1] }),
  end: fromTileLocal(tile, { x: shape.end[0], y: shape.end[1] }),
});

const shapeMargin = ({ kind, width, nativeZoom }: ShapeLook): number =>
  strokeWorldWidth(kind === "Arrow" ? Math.max(width, arrowHeadPx(width)) : width, nativeZoom);

export const shapeBounds = (look: ShapeLook, start: Point, end: Point): BBox => {
  const margin = shapeMargin(look);
  return {
    minX: Math.min(start.x, end.x) - margin,
    minY: Math.min(start.y, end.y) - margin,
    maxX: Math.max(start.x, end.x) + margin,
    maxY: Math.max(start.y, end.y) + margin,
  };
};

export const startShape = (
  kind: ShapeKind,
  fill: ShapeFill,
  rgb: number,
  width: number,
  style: StrokeStyle,
  zoom: number,
  at: Point,
): ShapeDraft => ({
  objectId: newObjectId(),
  kind,
  fill: FILLABLE[kind] ? fill : "None",
  rgb,
  width,
  style,
  nativeZoom: nativeLevel(zoom),
  start: at,
  end: at,
});

const placeShape = (
  base: Omit<Shape, "bbox" | "start" | "end">,
  look: ShapeLook,
  start: Point,
  end: Point,
): StoredObject | undefined => {
  const bbox = shapeBounds(look, start, end);
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const localStart = toTileLocal(tile, start);
  const localEnd = toTileLocal(tile, end);
  return {
    tile,
    object: {
      ...base,
      bbox,
      start: [localStart.x, localStart.y],
      end: [localEnd.x, localEnd.y],
    },
  };
};

export const finishShape = (draft: ShapeDraft): StoredObject | undefined => {
  const { start, end } = draft;
  const extent = Math.max(Math.abs(end.x - start.x), Math.abs(end.y - start.y));
  if (extent < strokeWorldWidth(MIN_SHAPE_PX, draft.nativeZoom)) return undefined;
  return placeShape(
    {
      type: "Shape",
      objectId: draft.objectId,
      nativeZoom: draft.nativeZoom,
      colour: nearestColour(draft.rgb),
      rgb: draft.rgb,
      size: nearestSize(draft.width),
      width: draft.width,
      style: draft.style,
      kind: draft.kind,
      fill: draft.fill,
    },
    draft,
    start,
    end,
  );
};

export const translateShape = (
  tile: Tile,
  shape: Shape,
  dx: number,
  dy: number,
): StoredObject | undefined => {
  const { start, end } = shapeWorldPoints(tile, shape);
  const { bbox: _bbox, start: _start, end: _end, ...base } = shape;
  return placeShape(
    base,
    shapeLook(shape),
    { x: start.x + dx, y: start.y + dy },
    { x: end.x + dx, y: end.y + dy },
  );
};

export const shapeScreenInk = (
  look: ShapeLook,
  start: Point,
  end: Point,
  toScreen: (world: Point) => Point,
  zoom: number,
): ShapeInk => ({
  kind: look.kind,
  filled: look.fill === "Tint" && FILLABLE[look.kind],
  style: look.style,
  start: toScreen(start),
  end: toScreen(end),
  lineWidth: strokeWorldWidth(look.width, look.nativeZoom) * zoom,
  head: strokeWorldWidth(arrowHeadPx(look.width), look.nativeZoom) * zoom,
});

type ArrowHead = { base: Point; wing: Point };

const outline = (ctx: CanvasRenderingContext2D, ink: ShapeInk): ArrowHead | undefined => {
  const { start, end } = ink;
  ctx.beginPath();
  if (ink.kind === "Rectangle") {
    ctx.rect(
      Math.min(start.x, end.x),
      Math.min(start.y, end.y),
      Math.abs(end.x - start.x),
      Math.abs(end.y - start.y),
    );
    return undefined;
  }
  if (ink.kind === "Ellipse") {
    ctx.ellipse(
      (start.x + end.x) / 2,
      (start.y + end.y) / 2,
      Math.abs(end.x - start.x) / 2,
      Math.abs(end.y - start.y) / 2,
      0,
      0,
      Math.PI * 2,
    );
    return undefined;
  }
  ctx.moveTo(start.x, start.y);
  const length = Math.hypot(end.x - start.x, end.y - start.y);
  if (ink.kind === "Line" || length === 0) {
    ctx.lineTo(end.x, end.y);
    return undefined;
  }
  const head = Math.min(ink.head, length);
  const ux = (end.x - start.x) / length;
  const uy = (end.y - start.y) / length;
  const base = { x: end.x - ux * head, y: end.y - uy * head };
  ctx.lineTo(base.x + ux * head * 0.2, base.y + uy * head * 0.2);
  return { base, wing: { x: -uy * head * ARROW_HEAD_SPREAD, y: ux * head * ARROW_HEAD_SPREAD } };
};

export const paintShape = (
  ctx: CanvasRenderingContext2D,
  ink: ShapeInk,
  colour: string,
  alpha = 1,
): void => {
  const highlighter = ink.style === "Highlighter";
  const base = highlighter ? alpha * HIGHLIGHTER_ALPHA : alpha;
  if (highlighter) ctx.globalCompositeOperation = "multiply";
  ctx.strokeStyle = colour;
  ctx.fillStyle = colour;
  ctx.lineWidth = ink.lineWidth;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const arrowHead = outline(ctx, ink);
  if (ink.filled) {
    ctx.globalAlpha = base * TINT_ALPHA;
    ctx.fill();
  }
  ctx.globalAlpha = base;
  if (ink.style === "Dashed") ctx.setLineDash(dashPattern(ink.lineWidth));
  ctx.stroke();
  ctx.setLineDash([]);
  if (arrowHead) {
    const { base: b, wing } = arrowHead;
    ctx.beginPath();
    ctx.moveTo(ink.end.x, ink.end.y);
    ctx.lineTo(b.x + wing.x, b.y + wing.y);
    ctx.lineTo(b.x - wing.x, b.y - wing.y);
    ctx.closePath();
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
};
import type { Point } from "@stallion/geometry";

export type PointerKind = "mouse" | "pen" | "touch";

export type Modifiers = { panTool: boolean; spaceDown: boolean };

export type DragInput = {
  first: boolean;
  last: boolean;
  cancelled: boolean;
  intentional: boolean;
  kind: PointerKind;
  button: number;
  point: Point;
  time: number;
};

export type PinchInput = { first: boolean; last: boolean; origin: Point; distance: number };

export type Effect =
  | { type: "StartStroke"; secondary: boolean; point: Point }
  | { type: "ExtendStroke" }
  | { type: "CommitStroke" }
  | { type: "DiscardStroke" }
  | { type: "Pan"; dx: number; dy: number }
  | { type: "Pinch"; anchor: Point; factor: number; dx: number; dy: number };

type DragMode =
  | { mode: "Idle" }
  | { mode: "Ignore" }
  | { mode: "Pending"; point: Point; time: number }
  | { mode: "Draw"; kind: PointerKind }
  | { mode: "Pan"; point: Point };

type PinchMode =
  | { mode: "Idle" }
  | { mode: "Ignore" }
  | { mode: "Track"; start: number; origin: Point; distance: number; zooming: boolean };

export type Input = {
  drag(input: DragInput, modifiers: Modifiers): Effect[];
  pinch(input: PinchInput): Effect[];
  tick(time: number): Effect[];
};

const PRIMARY = 0;
const MIDDLE = 1;
const SECONDARY = 2;

export const PENDING_MS = 60;
export const DRAG_THRESHOLD_PX = 6;
export const PINCH_ZOOM_THRESHOLD = 0.08;

export function createInput(): Input {
  let drag: DragMode = { mode: "Idle" };
  let pinch: PinchMode = { mode: "Idle" };
  let penSeen = false;

  const wantsPan = (input: DragInput, modifiers: Modifiers): boolean => {
    if (input.button === MIDDLE) return true;
    if (input.button !== PRIMARY) return false;
    if (modifiers.panTool || modifiers.spaceDown) return true;
    return input.kind === "touch" && penSeen;
  };

  const promote = (): Effect[] => {
    if (drag.mode !== "Pending") return [];
    const { point } = drag;
    drag = { mode: "Draw", kind: "touch" };
    return [{ type: "StartStroke", secondary: false, point }];
  };

  const begin = (input: DragInput, modifiers: Modifiers): Effect[] => {
    if (input.kind === "pen") penSeen = true;
    if (pinch.mode === "Track") {
      drag = { mode: "Ignore" };
      return [];
    }
    if (wantsPan(input, modifiers)) {
      drag = { mode: "Pan", point: input.point };
      return [];
    }
    if (input.button !== PRIMARY && input.button !== SECONDARY) {
      drag = { mode: "Ignore" };
      return [];
    }
    if (input.kind === "touch") {
      drag = { mode: "Pending", point: input.point, time: input.time };
      return [];
    }
    drag = { mode: "Draw", kind: input.kind };
    return [{ type: "StartStroke", secondary: input.button === SECONDARY, point: input.point }];
  };

  const step = (input: DragInput): Effect[] => {
    const effects: Effect[] = [];
    if (drag.mode === "Pending") {
      if (!input.intentional && input.time - drag.time < PENDING_MS) return [];
      effects.push(...promote());
    }
    if (drag.mode === "Draw") effects.push({ type: "ExtendStroke" });
    if (drag.mode === "Pan") {
      effects.push({
        type: "Pan",
        dx: input.point.x - drag.point.x,
        dy: input.point.y - drag.point.y,
      });
      drag = { mode: "Pan", point: input.point };
    }
    return effects;
  };

  const end = (input: DragInput): Effect[] => {
    const effects: Effect[] = [];
    if (drag.mode === "Pending" && !input.cancelled) effects.push(...promote());
    if (drag.mode === "Draw")
      effects.push({ type: input.cancelled ? "DiscardStroke" : "CommitStroke" });
    drag = { mode: "Idle" };
    return effects;
  };

  const startPinch = (input: PinchInput): Effect[] => {
    if (drag.mode === "Draw" && drag.kind !== "touch") {
      pinch = { mode: "Ignore" };
      return [];
    }
    const discard = drag.mode === "Draw";
    if (drag.mode !== "Idle") drag = { mode: "Ignore" };
    pinch = {
      mode: "Track",
      start: input.distance,
      origin: input.origin,
      distance: input.distance,
      zooming: false,
    };
    return discard ? [{ type: "DiscardStroke" }] : [];
  };

  const movePinch = (input: PinchInput): Effect[] => {
    if (pinch.mode !== "Track") return [];
    const { origin, distance } = input;
    const spread = pinch.start > 0 ? Math.abs(distance / pinch.start - 1) : 0;
    const zooming = pinch.zooming || spread > PINCH_ZOOM_THRESHOLD;
    const factor =
      pinch.zooming && pinch.distance > 0 && distance > 0 ? distance / pinch.distance : 1;
    const effect: Effect = {
      type: "Pinch",
      anchor: pinch.origin,
      factor,
      dx: origin.x - pinch.origin.x,
      dy: origin.y - pinch.origin.y,
    };
    pinch = { ...pinch, origin, distance, zooming };
    return [effect];
  };

  return {
    drag(input, modifiers) {
      if (input.first) {
        const effects = begin(input, modifiers);
        return input.last ? [...effects, ...end(input)] : effects;
      }
      return input.last ? end(input) : step(input);
    },
    pinch(input) {
      if (input.first) return startPinch(input);
      if (!input.last) return movePinch(input);
      pinch = { mode: "Idle" };
      return [];
    },
    tick(time) {
      return drag.mode === "Pending" && time - drag.time >= PENDING_MS ? promote() : [];
    },
  };
}

