import { fromTileLocal, MAX_LEVEL, tileKey } from "@stallion/geometry";
import { nearestSize, PENCIL_PX, type Stroke, widthOf } from "@stallion/schema";
import { afterEach, describe, expect, test, vi } from "vitest";
import {
  finishDraft,
  PENCIL_SIZES,
  sliderToWidth,
  startDraft,
  strokeFrame,
  strokeWorldWidth,
  translateStroke,
  WIDTH_SLIDER_STEPS,
  widthToSlider,
} from "./stroke";

describe("width", () => {
  test("maps each size to its width and each width to the nearest size", () => {
    for (const size of PENCIL_SIZES) {
      expect(widthOf({ size })).toBe(PENCIL_PX[size]);
      expect(nearestSize(PENCIL_PX[size])).toBe(size);
    }
    expect(widthOf({ size: "Large", width: 1 })).toBe(1);
    expect(nearestSize(0.5)).toBe("Small");
    expect(nearestSize(4.8)).toBe("Small");
    expect(nearestSize(5)).toBe("Medium");
    expect(nearestSize(12)).toBe("Medium");
    expect(nearestSize(13)).toBe("Large");
    expect(nearestSize(96)).toBe("Large");
  });

  test("commits the draft width and the nearest size, and scales the world width by it", () => {
    const draft = startDraft(0, 60, "Pen", 1);
    draft.points.push([10, 10, 0.5], [40, 20, 0.5]);
    const stroke = finishDraft(draft)?.object as Stroke;
    expect(stroke).toMatchObject({ width: 60, size: "Large" });
    expect(strokeWorldWidth(60, 0) / strokeWorldWidth(1, 0)).toBe(60);
  });

  test("the slider spans 0.5 to 96 and round-trips every preset width", () => {
    expect(sliderToWidth(0)).toBe(0.5);
    expect(sliderToWidth(WIDTH_SLIDER_STEPS)).toBe(96);
    for (const width of [0.5, 1, 2, 3, 8, 20, 40, 60, 96]) {
      expect(Math.abs(sliderToWidth(widthToSlider(width)) - width) / width).toBeLessThan(0.06);
    }
  });
});

describe("finishDraft", () => {
  afterEach(() => vi.unstubAllGlobals());

  test("commits the draft style", () => {
    const draft = startDraft(0, 8, "Dashed", 1);
    draft.points.push([10, 10, 0.5], [40, 20, 0.5]);
    expect(finishDraft(draft)?.object).toMatchObject({ style: "Dashed" });
  });

  test("commits a stroke outside a secure context, where crypto.randomUUID is missing", () => {
    vi.stubGlobal("crypto", { getRandomValues: crypto.getRandomValues.bind(crypto) });
    const draft = startDraft(0, 8, "Pen", 1);
    draft.points.push([10, 10, 0.5], [40, 20, 0.5]);
    const stored = finishDraft(draft);
    expect(stored?.object.objectId).toMatch(/^[0-9a-z]{9}[0-9a-f]{12}$/);
  });
});

describe("strokeFrame", () => {
  test("keeps a stroke across the world origin drawable in float32 canvas paths", () => {
    const zoom = 1 / 9;
    const draft = startDraft(0, 8, "Pen", zoom);
    const circle = Array.from({ length: 25 }, (_, i) => {
      const angle = (i / 24) * 2 * Math.PI;
      return { x: 600 + (300 * Math.cos(angle)) / zoom, y: 960 + (300 * Math.sin(angle)) / zoom };
    });
    for (const { x, y } of circle) draft.points.push([x, y, 0.5]);
    const stored = finishDraft(draft);
    if (stored?.object.type !== "Stroke") throw new Error("stroke not placed");
    expect(stored.tile.level).toBe(MAX_LEVEL);

    const frame = strokeFrame(stored.tile, stored.object);
    frame.points.forEach(([x, y], i) => {
      const drawn = circle[i];
      expect(frame.origin.x + Math.fround(x) * frame.scale).toBeCloseTo(drawn?.x ?? Number.NaN, 0);
      expect(frame.origin.y + Math.fround(y) * frame.scale).toBeCloseTo(drawn?.y ?? Number.NaN, 0);
    });
  });
});

describe("translateStroke", () => {
  test("re-places a stroke dragged across a tile boundary and keeps its world points", () => {
    const draft = startDraft(0, 3, "Pen", 1);
    draft.points.push([10, 10, 0.5], [40, 20, 0.5]);
    const stored = finishDraft(draft);
    if (stored?.object.type !== "Stroke") throw new Error("no stroke");
    const moved = translateStroke(stored.tile, stored.object, 300, 0);
    expect(moved && tileKey(moved.tile)).not.toBe(tileKey(stored.tile));
    const [first] = moved?.object.type === "Stroke" ? moved.object.points : [];
    const world = first && moved && fromTileLocal(moved.tile, { x: first[0], y: first[1] });
    expect(world?.x).toBeCloseTo(310);
    expect(world?.y).toBeCloseTo(10);
  });
});
import type { StoredObject } from "@stallion/client-store";
import type { LiveObjects } from "@stallion/client-sync";
import type { Shape } from "@stallion/schema";
import { afterEach, expect, test, vi } from "vitest";
import { shapeWorldPoints } from "./shape";
import { createSurface, INK_ALPHA, PAPER, type Tool } from "./surface";
import type { Awareness, DrawingSource } from "./sync";

const stored: StoredObject = {
  tile: { level: 0, tx: 0, ty: 0 },
  object: {
    type: "Stroke",
    objectId: "000000000aaaaaaaaaaaa",
    nativeZoom: 0,
    bbox: { minX: 0, minY: 0, maxX: 10, maxY: 10 },
    colour: 0,
    rgb: 0x1f2328,
    size: "Medium",
    style: "Pen",
    points: [
      [1, 1, 0.5],
      [8, 8, 0.5],
    ],
  },
};

type Handler = (state: { event: unknown; intentional: boolean }) => void;

const gesture = vi.hoisted(() => ({ handlers: {} as Record<string, Handler> }));

vi.mock("@use-gesture/vanilla", () => ({
  Gesture: class {
    constructor(_target: unknown, handlers: Record<string, Handler>) {
      gesture.handlers = handlers;
    }
    destroy() {}
  },
}));

afterEach(() => vi.unstubAllGlobals());

const PENCIL: Tool = {
  width: 8,
  style: "Pen",
  primary: 0,
  secondary: 4,
  shape: "Rectangle",
  fill: "None",
  mode: "Pencil",
};

type Screen = { x: number; y: number };

const pointer = (type: string, { x, y }: Screen) => ({
  type,
  pointerId: 1,
  pointerType: "mouse",
  button: 0,
  clientX: x,
  clientY: y,
  timeStamp: 0,
  preventDefault: () => undefined,
});

const dragAlong = (from: Screen, to: Screen) => {
  const onDrag = gesture.handlers.onDrag;
  if (!onDrag) throw new Error("the surface bound no drag handler");
  onDrag({ event: pointer("pointerdown", from), intentional: false });
  onDrag({ event: pointer("pointermove", to), intentional: true });
  onDrag({ event: pointer("pointerup", to), intentional: true });
};

const harness = (initial: StoredObject[], awareness?: Awareness) => {
  const calls: string[] = [];
  const commits: StoredObject[] = [];
  const erased: string[] = [];
  let tool = PENCIL;
  const context = {
    beginPath: () => undefined,
    rect: () => undefined,
    ellipse: () => undefined,
    moveTo: () => undefined,
    lineTo: () => undefined,
    closePath: () => undefined,
    setLineDash: () => undefined,
    stroke: function (this: { strokeStyle: string }) {
      calls.push(`stroke ${this.strokeStyle}`);
    },
    strokeStyle: "",
    setTransform: () => undefined,
    clearRect: () => calls.push("clearRect"),
    fillRect: function (this: { fillStyle: string }) {
      calls.push(`fillRect ${this.fillStyle}`);
    },
    fill: function (this: { fillStyle: string; globalAlpha: number }) {
      calls.push(this.globalAlpha === 1 ? `fill ${this.fillStyle}` : `ink ${this.fillStyle}`);
    },
    fillStyle: "",
    globalAlpha: 1,
  };
  const listen = { addEventListener: () => undefined, removeEventListener: () => undefined };
  vi.stubGlobal("window", { ...listen, devicePixelRatio: 1 });
  vi.stubGlobal("localStorage", { getItem: () => null, setItem: () => undefined });
  const frames: FrameRequestCallback[] = [];
  vi.stubGlobal("requestAnimationFrame", (callback: FrameRequestCallback) => frames.push(callback));
  vi.stubGlobal("cancelAnimationFrame", () => undefined);
  vi.stubGlobal(
    "ResizeObserver",
    class {
      observe() {}
      disconnect() {}
    },
  );
  vi.stubGlobal(
    "Path2D",
    class {
      moveTo() {}
      lineTo() {}
      closePath() {}
    },
  );
  const canvas = {
    ...listen,
    clientWidth: 400,
    clientHeight: 300,
    width: 0,
    height: 0,
    getContext: () => context,
    getBoundingClientRect: () => ({ left: 0, top: 0 }),
  } as unknown as HTMLCanvasElement;
  const store = new Map(initial.map((entry) => [entry.object.objectId, entry]));
  const observers = new Set<(changed: ReadonlySet<string>) => void>();
  const objects = Object.assign(store, {
    observe(listener: (changed: ReadonlySet<string>) => void) {
      observers.add(listener);
      return () => observers.delete(listener);
    },
  }) as LiveObjects;
  const source: DrawingSource = {
    view: () => undefined,
    commit: (entry) => commits.push(entry),
    erase: (objectId) => erased.push(objectId),
    objects,
    hints: { current: [], observe: () => () => undefined },
    history: {
      undo: () => undefined,
      redo: () => undefined,
      checkpoint: () => undefined,
      canUndo: false,
      canRedo: false,
      observe: () => () => undefined,
    },
    awareness,
    close: () => Promise.resolve(),
  };
  const surface = createSurface(canvas, "board", source, () => tool);
  const paint = () => {
    calls.length = 0;
    for (const callback of frames.splice(0)) callback(0);
    return [...calls];
  };
  const arrive = (entry: StoredObject) => {
    store.set(entry.object.objectId, entry);
    for (const observer of observers) observer(new Set([entry.object.objectId]));
  };
  const use = (next: Partial<Tool>) => {
    tool = { ...tool, ...next };
  };
  return { surface, paint, arrive, use, commits, erased };
};

test("each frame paints the paper before any stroke", () => {
  const { surface, paint } = harness([stored]);
  const calls = paint();
  surface.dispose();

  expect(calls).toEqual([`fillRect ${PAPER}`, "fill #1f2328"]);
});

test("a remote stroke in progress gives way to its committed object", () => {
  const ink = {
    strokeId: stored.object.objectId,
    colour: 4,
    size: "Medium",
    nativeZoom: 0,
    from: 0,
    points: [
      [1, 1, 0.5],
      [8, 8, 0.5],
    ],
  };
  const states = new Map<number, unknown>([
    [1, {}],
    [2, { ink }],
  ]);
  const awareness = {
    clientID: 1,
    getStates: () => states,
    on: () => undefined,
    off: () => undefined,
    setLocalStateField: () => undefined,
  } as unknown as Awareness;
  const { surface, paint, arrive } = harness([], awareness);

  expect(INK_ALPHA).toBeLessThan(1);
  expect(paint()).toEqual([`fillRect ${PAPER}`, "ink #0090ff"]);

  arrive({ ...stored, object: { ...stored.object, colour: 4, rgb: 0x0090ff } });
  const calls = paint();
  surface.dispose();

  expect(calls).toEqual([`fillRect ${PAPER}`, "fill #0090ff"]);
});

test("draws a rectangle, moves it by its edge and erases it where it landed", () => {
  const { surface, paint, arrive, use, commits, erased } = harness([]);
  use({ mode: "Shape", shape: "Rectangle", fill: "Tint", primary: 0x8e4ec6 });
  dragAlong({ x: 100, y: 100 }, { x: 200, y: 150 });

  const [drawn] = commits;
  if (drawn?.object.type !== "Shape") throw new Error("no shape committed");
  expect(drawn.object).toMatchObject({ kind: "Rectangle", fill: "Tint", rgb: 0x8e4ec6 });
  expect(shapeWorldPoints(drawn.tile, drawn.object)).toEqual({
    start: { x: 100, y: 100 },
    end: { x: 200, y: 150 },
  });
  arrive(drawn);
  expect(paint()).toEqual([`fillRect ${PAPER}`, "ink #8e4ec6", "stroke #8e4ec6"]);

  use({ mode: "Select" });
  dragAlong({ x: 150, y: 100 }, { x: 150, y: 300 });
  const moved = commits[1];
  if (moved?.object.type !== "Shape") throw new Error("no move committed");
  expect(moved.object.objectId).toBe(drawn.object.objectId);
  const { start, end } = shapeWorldPoints(moved.tile, moved.object as Shape);
  expect(start.x).toBeCloseTo(100, 9);
  expect(start.y).toBeCloseTo(300, 9);
  expect(end.x).toBeCloseTo(200, 9);
  expect(end.y).toBeCloseTo(350, 9);
  arrive(moved);

  use({ mode: "Eraser" });
  dragAlong({ x: 150, y: 125 }, { x: 150, y: 125 });
  expect(erased).toEqual([]);
  dragAlong({ x: 150, y: 325 }, { x: 150, y: 325 });
  surface.dispose();

  expect(erased).toContain(drawn.object.objectId);
});

